python3 << 'EOF'
import re

# Option 1: Keep all letters (ASCII and Unicode)
def slugify_v1(text):
    text = text.strip().lower()
    return re.sub(r"[^a-z0-9]+", "-", text).strip("-")

# Option 2: Keep all Unicode letters
def slugify_v2(text):
    text = text.strip().lower()
    # Match any character that is not a digit or non-word character
    return re.sub(r"[^\w]+", "-", text).strip("-")

test_cases = [
    "hello world",
    "C++ rocks!",
    "héllo wörld",
]

for tc in test_cases:
    print(f"{tc!r} -> {slugify_v1(tc)!r}")
    print(f"{'-' * 50}")
EOF

